// Eingabe der Runtime: { event_id, title?, start?, end?, location?, description?, calendar? }
const incoming = $input.first().json;
const inp = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
if (typeof inp.event_id !== 'string' || inp.event_id.trim() === '') {
  throw new Error('cal-update: Feld "event_id" fehlt');
}
const update = {};
if (typeof inp.title === 'string' && inp.title) update.summary = inp.title;
if (typeof inp.start === 'string' && inp.start) update.start = inp.start;
if (typeof inp.end === 'string' && inp.end) update.end = inp.end;
if (typeof inp.location === 'string' && inp.location) update.location = inp.location;
if (typeof inp.description === 'string' && inp.description) update.description = inp.description;
if (Object.keys(update).length === 0) {
  throw new Error('cal-update: kein zu aenderndes Feld angegeben');
}
return [{ json: {
  eventId: inp.event_id.trim(),
  calendar: typeof inp.calendar === 'string' && inp.calendar ? inp.calendar : 'primary',
  update
} }];

const e = $input.first().json || {};
return [{ json: {
  event_id: String(e.id || ''),
  html_link: e.htmlLink || '',
  calendar: (e.organizer && e.organizer.email) || 'primary',
  updated: !!e.id
} }];
